/bin/bash -lc "python3 - <<'PY'
import json, os, pathlib, shutil, subprocess, tempfile

archive = pathlib.Path(\"release/engineering-tally-fixture-1.1.0.tgz\")
with tempfile.TemporaryDirectory(prefix=\".tally-check-\", dir=\".\") as path:
    folder = pathlib.Path(path).resolve()
    shutil.copy2(archive, folder)
    env = os.environ | {\"npm_config_cache\": str(folder / \".npm-cache\"), \"TMPDIR\": str(folder)}
    subprocess.run([\"npm\", \"install\", \"--offline\", \"--no-audit\", \"--no-fund\", \"--ignore-scripts\", f\"./{archive.name}\"], cwd=folder, env=env, check=True)
    bin_path = \"./node_modules/.bin/tally\"
    print(\"Installed bin:\", (folder / bin_path).readlink())
    for args in [[\"--version\"], [\"--help\"], [\"sum\", \"2\", \"3\", \"--machine\"], [\"sum\", \"2\", \"abc\", \"--machine\"], [\"sum\", \"2\", \"3\", \"--json\"]]:
        result = subprocess.run([bin_path, *args], cwd=folder, capture_output=True, text=True)
        print(args, result.returncode, repr(result.stdout), repr(result.stderr))
        if args == [\"sum\", \"2\", \"3\", \"--machine\"]:
            assert result.returncode == 0 and not result.stderr and json.loads(result.stdout) == {\"sum\": 5}
        elif args[0] == \"sum\":
            assert result.returncode == 2 and not result.stdout and result.stderr == \"Number expected\\n\"
        else:
            assert result.returncode == 0 and not result.stderr
PY"
